use vstd::prelude::*;

verus! {

fn bitwise_and(a: Vec<u8>, b: Vec<u8>) -> (result: Vec<u8>)
    requires a.len() == b.len(),
    ensures 
        result.len() == a.len(),
        forall|i: int| 0 <= i < result.len() ==> result[i] == (a[i] & b[i])
{
    let n = a.len();
    let mut res: Vec<u8> = Vec::new();
    let mut i: usize = 0;
    while i < n
        invariant
            a.len() == n,
            b.len() == n,
            i <= n,
            res.len() == i,
            forall|j: int| 0 <= j < i as int ==> res[j] == (a[j] & b[j]),
        decreases n - i
    {
        let v = a[i] & b[i];
        res.push(v);
        i += 1;
    }
    res
}

}
fn main() {}

use vstd::prelude::*;

verus! {

fn bitwise_or(a: Vec<u8>, b: Vec<u8>) -> (result: Vec<u8>)
    requires a.len() == b.len(),
    ensures 
        result.len() == a.len(),
        forall|i: int| 0 <= i < result.len() ==> result[i] as u32 == (a[i] as u32 | b[i] as u32),
{
    let n = a.len();
    let mut result: Vec<u8> = Vec::new();
    let mut i: usize = 0;

    while i < n
        invariant
            a.len() == n,
            b.len() == n,
            result.len() == i,
            0 <= i as int <= n as int,
            forall|j: int| 0 <= j < i as int ==> result[j] as u32 == (a[j] as u32 | b[j] as u32),
        decreases (n as int) - (i as int)
    {
        let ai = a[i];
        let bi = b[i];
        let v = ai | bi;
        result.push(v);

        // Link exec indexing with spec view for this index
        assert(a@[i as int] == ai);
        assert(b@[i as int] == bi);
        // The pushed element is at position i
        assert(result@[i as int] == v);

        i += 1;
    }

    result
}

}
fn main() {}

use vstd::prelude::*;

verus! {

fn bitwise_xor(a: Vec<u8>, b: Vec<u8>) -> (result: Vec<u8>)
    requires 
        a.len() == b.len(),
        a.len() > 0,
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i < a@.len() ==> result@[i] == a@[i] ^ b@[i],
{
    let len = a.len();
    let mut res: Vec<u8> = Vec::new();
    let mut i: usize = 0;

    while i < len
        invariant
            len == a.len(),
            len == b.len(),
            i <= len,
            res.len() == i,
            forall|j: int| 0 <= j < i as int ==> res@[j] == a@[j] ^ b@[j],
        decreases len as int - i as int
    {
        let x = a[i];
        let y = b[i];
        res.push(x ^ y);
        // res.len() was i, after push it's i + 1; the new element is at index i
        assert(res@[i as int] == a@[i as int] ^ b@[i as int]);
        i += 1;
    }

    assert(i == len);
    res
}

}
fn main() {}

