use vstd::prelude::*;

verus! {

fn equal(a: Vec<i8>, b: Vec<i8>) -> (result: Vec<bool>)
    requires a.len() == b.len(),
    ensures 
        result.len() == a.len(),
        forall|i: int| 0 <= i < a@.len() ==> result@[i] == (a@[i] == b@[i])
{
    let ghost a_seq = a@;
    let ghost b_seq = b@;

    let n = a.len();
    let mut result: Vec<bool> = Vec::new();
    let mut i: usize = 0;

    while i < n
        invariant
            // Inputs remain unchanged
            a@ == a_seq,
            b@ == b_seq,
            n == a.len(),
            n == b.len(),
            // Progress and length relation
            i <= n,
            result.len() == i,
            // Correctness for the portion built so far
            forall|j: int| 0 <= j < i as int ==> result@[j] == (a_seq[j] == b_seq[j])
        decreases n - i
    {
        let ai = a[i];
        let bi = b[i];
        result.push(ai == bi);
        i += 1;
    }

    result
}

}
fn main() {}

use vstd::prelude::*;

verus! {

fn greater(a: Vec<i8>, b: Vec<i8>) -> (result: Vec<bool>)
    requires a.len() == b.len(),
    ensures 
        result.len() == a.len(),
        forall|i: int| 0 <= i < a.len() ==> result[i] == (a[i] as i32 > b[i] as i32)
{
    let n = a.len();
    let mut res: Vec<bool> = Vec::new();
    let mut i: usize = 0;
    while i < n
        invariant
            a.len() == n,
            b.len() == n,
            i <= n,
            res.len() == i,
            forall|j: int| 0 <= j < i as int ==> res[j] == ((a[j] as i32) > (b[j] as i32)),
        decreases n - i
    {
        // safe to index since i < n == a.len() == b.len()
        let ai = a[i];
        let bi = b[i];
        let cond = (ai as i32) > (bi as i32);
        res.push(cond);
        // after push, res[i] is the newly pushed element
        assert(res[i as int] == cond);
        i += 1;
    }
    res
}

}
fn main() {}

use vstd::prelude::*;

verus! {

fn greater_equal(a: Vec<i8>, b: Vec<i8>) -> (result: Vec<bool>)
    requires a.len() == b.len(),
    ensures 
        result.len() == a.len(),
        forall|i: int| 0 <= i < a.len() ==> result[i] == (a[i] as int >= b[i] as int)
{
    let mut res: Vec<bool> = Vec::new();
    let mut i: usize = 0;
    while i < a.len()
        invariant
            a.len() == b.len(),
            res.len() == i,
            0 <= i as int <= a.len() as int,
            forall|j: int| 0 <= j < i as int ==> res[j] == (a[j] as int >= b[j] as int)
        decreases a.len() as int - i as int
    {
        let ai = a[i];
        let bi = b[i];
        let val = ai >= bi;
        proof {
            assert(val == (ai as int >= bi as int));
        }
        res.push(val);
        i += 1;
    }
    res
}

}
fn main() {}

