use vstd::prelude::*;

verus! {

fn less(a: Vec<i8>, b: Vec<i8>) -> (result: Vec<bool>)
    requires a.len() == b.len(),
    ensures 
        result.len() == a.len(),
        forall|i: int| 0 <= i < a@.len() ==> result@[i] == (a@[i] < b@[i])
{
    let n = a.len();
    let mut res: Vec<bool> = Vec::new();
    let mut i: usize = 0;
    while i < n
        invariant
            a.len() == n,
            b.len() == n,
            i <= n,
            res.len() == i,
            forall|j: int| 0 <= j < i as int ==> res@[j] == (a@[j] < b@[j]),
        decreases n - i
    {
        let prev_i = i;
        let ai = a[prev_i];
        let bi = b[prev_i];
        let val = ai < bi;
        res.push(val);
        i += 1;

        // connect the pushed value with the spec view
        assert(a@[prev_i as int] == ai);
        assert(b@[prev_i as int] == bi);
        assert(res@[prev_i as int] == val);
        assert(res@[prev_i as int] == (a@[prev_i as int] < b@[prev_i as int]));
    }
    res
}

}
fn main() {}

