use vstd::prelude::*;

verus! {

fn polyder(poly: Vec<i8>, m: i8) -> (result: Vec<i8>)
    requires 
        m > 0,
        m <= poly.len() as i8,
    ensures 
        result.len() == poly.len() - (m as usize),
{
    // From the preconditions, m is positive and not greater than poly.len().
    // This ensures the subtraction below will not underflow.
    assert((m as usize) <= poly.len());

    let target_len: usize = poly.len() - (m as usize);

    let result = vec![0i8; target_len];

    result
}

}
fn main() {}

use vstd::prelude::*;

verus! {

fn sign(a: Vec<i32>) -> (result: Vec<i32>)
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i < a.len() ==> {
            (a[i] > 0 ==> result[i] == 1) &&
            (a[i] == 0 ==> result[i] == 0) &&
            (a[i] < 0 ==> result[i] == -1)
        }
{
    let mut out: Vec<i32> = Vec::new();
    let mut i: usize = 0;
    while i < a.len()
        invariant
            out.len() == i,
            i <= a.len(),
            forall|j: int| 0 <= j < i as int ==> {
                (a[j] > 0 ==> out[j] == 1) &&
                (a[j] == 0 ==> out[j] == 0) &&
                (a[j] < 0 ==> out[j] == -1)
            }
        decreases a.len() - i
    {
        let x = a[i];
        let s = if x > 0 { 1 } else if x == 0 { 0 } else { -1 };
        out.push(s);
        proof {
            assert(a[i as int] > 0 ==> out[i as int] == 1);
            assert(a[i as int] == 0 ==> out[i as int] == 0);
            assert(a[i as int] < 0 ==> out[i as int] == -1);
        }
        i += 1;
    }
    out
}

}
fn main() {}

